/**
 * Unit tests for {@link org.apache.commons.math3.fraction.Fraction#percentageValue()}
 */
public class Fraction_percentageValue_TriageGen5Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testPercentageValue_fromIntegerConstructor() {
        // Fraction(1) -> 1/1. 1 * 100 = 100.0
        Fraction fraction = new Fraction(1);
        double expected = 100.0;
        Assert.assertEquals(expected, fraction.percentageValue(), DELTA);
    }












}

